// План specs/dashboard.md 2.5 (кейс DB-08). Ширина 1023 (Chrome) и Pixel 7: совета нет. admin, компания «test». Только просмотр (@prod-safe).
import { test, expect, Page } from '@playwright/test';
import { ADMIN_STATE } from '../addresses/address-helpers';
import { greetingCard } from './dashboard-helpers';
import {
  expectNoInvoicesDueInCard, hideTipButton, openDashboardFresh, removeTipKeys, waitTipWindowPassed,
} from './dashboard-tips-helpers';

test.use({ storageState: ADMIN_STATE });

async function expectNoTipInCard(page: Page) {
  await openDashboardFresh(page, 'en');
  await waitTipWindowPassed(page);
  await expect(greetingCard(page)).toBeVisible();
  await expect(hideTipButton(page, 'en').filter({ visible: true }), 'видимых кнопок «Hide this tip» нет').toHaveCount(0);
  await expectNoInvoicesDueInCard(page);
}

test.describe('Дашборд уже 1024: в карточке приветствия нет совета и нет «Invoices due» (#444b9ee7)', () => {
  test.afterEach(async ({ page }) => { await removeTipKeys(page); });

  test.describe('ширина 1023', () => {
    test.use({ viewport: { width: 1023, height: 900 } });
    test('Dashboard at 1023px: greeting card has no tip and no "Invoices due" #444b9ee7 @desktop @prod-safe', async ({ page }) => {
      await expectNoTipInCard(page);
    });
  });

  test('Phone dashboard (Pixel 7): greeting card has no tip and no "Invoices due" #444b9ee7 @android @prod-safe', async ({ page }) => {
    await expectNoTipInCard(page);
  });
});
